// Router-Output parsen, validieren, Klärungspfad, Keyword-Fallback, Whitelist
const rawOutput = $input.first().json.output;
const metadata = $('Prepare Router Input').first().json.metadataFull;
const validIds = metadata.prompts.map(p => p.id);
const userQuestion = $('Prepare Router Input').first().json.userQuestion;
const sessionId = $('Prepare Router Input').first().json.sessionId;
const userId = $('Prepare Router Input').first().json.userId;

// Robuste JSON-Extraktion (LLMs verpacken manchmal in Codefences)
let parsed;
try {
  const cleaned = rawOutput.replace(/```json|```/g, '').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : cleaned);
} catch (e) {
  parsed = null;
}

// ===== KEYWORD-FALLBACK (Notbremse bei Parse-Fehler) =====
function keywordFallback(question) {
  const q = question.toLowerCase();
  if (q.includes('befrist'))                           return 'befristungs-pilot';
  if (q.includes('arbzg') || (q.includes('arbeitszeit') && !q.includes('mitbestimmung')))
                                                       return 'arbeitszeit-kompass';
  if (q.includes('bonus') || q.includes('zielvereinbarung') || q.includes('variable vergütung'))
                                                       return 'boni-pruefer';
  if (q.includes('klausel') && !q.includes('bv'))      return 'klausel-check';
  if (q.includes('abmahn'))                            return 'abmahnungs-assistent';
  if (q.includes('vergleich') && q.includes('klage'))  return 'vergleichs-stratege';
  if (q.includes('prozess') && (q.includes('klage') || q.includes('gericht')))
                                                       return 'prozess-lotse';
  if (q.includes('kündig'))                            return 'kundigungs-prufer';
  if (q.includes('agg') || q.includes('diskriminier')) return 'agg-check';
  if (q.includes('versetz'))                           return 'versetzungs-check';
  if (q.includes('einigungsstelle'))                   return 'einigungsstellen-check';
  if (q.includes('widerspruch') && q.includes('betriebsrat'))
                                                       return 'br-konter-check';
  if (q.includes('betriebsvereinbarung') || q.includes(' bv '))
                                                       return 'mbr-architekt';
  if (q.includes('verhandl') && q.includes('betriebsrat'))
                                                       return 'verhandlungs-kompass';
  if (q.includes('mitbestimmung'))                     return 'br-kompass';
  if (q.includes('betriebsrat'))                       return 'br-kompass';
  if (q.includes('risiko'))                            return 'risiko-radar';
  if (q.includes('option') && (q.includes(' vs ') || q.includes('vergleich')))
                                                       return 'entscheidungs-pilot';
  return null; // null = kein klarer Match → Klärung statt blindem Default
}

// ===== KLÄRUNGS-OBJEKT bauen =====
function buildClarifyResult(question, customQuestion) {
  return {
    prompt_id: 'clarify',
    target_agent: 'clarify',
    depth: 'none',
    confidence: 'low',
    user_question: question,
    reasoning: 'Frage zu unklar oder mehrdeutig — Rückfrage erforderlich',
    clarification_question: customQuestion || 'Können Sie Ihr Anliegen bitte konkretisieren? Geht es zum Beispiel um eine Kündigung, eine Versetzung, eine Betriebsratsangelegenheit, eine Vertragsklausel oder ein anderes Thema?'
  };
}

// ===== ENTSCHEIDUNGSBAUM =====
let isClarification = false;

if (!parsed) {
  // Parse-Fehler → direkt klären statt zu raten
  parsed = buildClarifyResult(userQuestion, null);
  parsed.reasoning = 'Parse-Fehler im Router-Output → Klärung statt Default';
  isClarification = true;
} else if (parsed.prompt_id === 'clarify') {
  // Router hat selbst um Klärung gebeten
  parsed.target_agent = 'clarify';
  parsed.depth = 'none';
  parsed.confidence = parsed.confidence || 'low';
  parsed.clarification_question = parsed.clarification_question || 
    'Können Sie Ihr Anliegen bitte konkretisieren?';
  isClarification = true;
} else if (!validIds.includes(parsed.prompt_id)) {
  // Halluzinierte ID → Keyword-Fallback, sonst Klärung
  const fbId = keywordFallback(userQuestion);
  if (fbId) {
    const fbMeta = metadata.prompts.find(p => p.id === fbId);
    parsed = {
      prompt_id: fbId,
      target_agent: ['lr-taktiker','ar-lotse','br-kompass','mbr-check'].includes(fbId) ? 'main' : 'spezialist',
      depth: fbMeta ? fbMeta.depth : 'full',
      confidence: 'low',
      user_question: userQuestion,
      reasoning: 'Fallback (Whitelist): ' + (parsed.prompt_id || '?') + ' ungültig → Keyword-Match → ' + fbId
    };
  } else {
    parsed = buildClarifyResult(userQuestion, null);
    parsed.reasoning = 'Router-ID ungültig und Keyword-Fallback ergab keinen klaren Match → Klärung';
    isClarification = true;
  }
} else if (parsed.confidence === 'low' && parsed.prompt_id !== 'clarify') {
  // Niedrige Confidence → lieber nachfragen
  const fbMeta = metadata.prompts.find(p => p.id === parsed.prompt_id);
  const alternatives = (fbMeta && fbMeta.related) ? fbMeta.related.slice(0,2) : [];
  const altText = alternatives.length > 0
    ? ` Mögliche Richtungen: ${parsed.prompt_id}` + alternatives.map(a => `, ${a}`).join('') + '.'
    : '';
  parsed = buildClarifyResult(
    userQuestion,
    `Ich bin nicht ganz sicher, wie ich Ihre Frage am besten einordnen soll.${altText} Können Sie kurz konkretisieren, was genau Sie wissen möchten?`
  );
  parsed.reasoning = 'Router-Confidence low bei gültiger ID → vorsichtshalber Klärung';
  isClarification = true;
}

// ===== ROUTING-PFAD A: Klärung =====
if (isClarification) {
  return [{
    json: {
      ...parsed,
      isClarification: true,
      sessionId,
      userId
    }
  }];
}

// ===== ROUTING-PFAD B: regulärer Executor =====
const promptMeta = metadata.prompts.find(p => p.id === parsed.prompt_id);
const baseUrl = metadata._meta.base_url_raw;
const promptUrl = baseUrl + (promptMeta.file || parsed.prompt_id + '_Prompt.md');

return [{
  json: {
    ...parsed,
    isClarification: false,
    sessionId,
    userId,
    promptFile: promptMeta.file || (parsed.prompt_id + '_Prompt.md'),
    promptUrl,
    promptName: promptMeta.name,
    related: promptMeta.related || [],
    relatedDetails: (promptMeta.related || []).map(rid => {
      const r = metadata.prompts.find(p => p.id === rid);
      return r ? { id: r.id, name: r.name, hint: r.hint } : null;
    }).filter(Boolean)
  }
}];

// System-Prompt-Bundle: .md + Qdrant-Kontext + related-Buttons-Instruktion + Eskalations-Hinweis
const mdContent = $('Load Prompt .md from GitHub').first().json.data || $('Load Prompt .md from GitHub').first().json;
const routing = $('Parse + Validate Router Output').first().json;
const metadata = $('Load Metadata from GitHub').first().json;

// Eskalations-Kandidat: bei quick-Prompts, suche im related-Array nach einem full-Prompt
const currentPrompt = metadata.prompts.find(p => p.id === routing.prompt_id);
let escalationCandidate = null;
if (currentPrompt && currentPrompt.depth === 'quick' && currentPrompt.related) {
  for (const relId of currentPrompt.related) {
    const rel = metadata.prompts.find(p => p.id === relId);
    if (rel && rel.depth === 'full') {
      escalationCandidate = { id: rel.id, name: rel.name, description: rel.description };
      break;
    }
  }
}

// Qdrant-Kontext: frühere Fälle aus dieser Session
let pastContext = '';
try {
  const qdrantResults = $('Qdrant Retrieve').first().json;
  const points = qdrantResults && qdrantResults.result && qdrantResults.result.points;
  if (points && points.length > 0) {
    pastContext = '\n\n---\n\nFRÜHERE FÄLLE / KONTEXT DES BEARBEITERS (sessionübergreifend):\n' +
      points.map((p, i) => {
        const pl = p.payload || {};
        return `[${i + 1}] ${pl.timestamp || 'früher'} | Prompt: ${pl.promptName || '?'}\n` +
               `   Frage: ${pl.question || ''}\n` +
               `   Antwort (gekürzt): ${(pl.answer || '').slice(0, 500)}...`;
      }).join('\n\n') +
      '\n\nNutze diesen Kontext, wenn er für die aktuelle Frage relevant ist. Wenn der vorherige Fall denselben Sachverhalt betraf, baue darauf auf statt von vorne anzufangen.';
  }
} catch (e) {
  // Qdrant leer oder nicht verfügbar — kein Problem, einfach ohne Kontext weiterlaufen
}

const relatedSection = routing.relatedDetails.length > 0
  ? '\n\n---\n\nVERFÜGBARE FOLGEPROMPTS (für Empfehlung am Ende):\n' +
    routing.relatedDetails.map(r => `- [${r.id}] ${r.name}: ${r.description}`).join('\n')
  : '';

const escalationSection = escalationCandidate
  ? '\n\n---\n\nESKALATIONS-OPTION (Quick → Full):\nDieser Prompt ist eine Schnellprüfung. Falls dein Ergebnis Vertiefungsbedarf signalisiert (komplexer Fall, hohes Risiko, viele offene Fragen), weise am Ende deiner Antwort auf folgenden Full-Prompt hin:\n- [' + escalationCandidate.id + '] ' + escalationCandidate.name + ': ' + escalationCandidate.description
  : '';

const outputInstruction = '\n\n---\n\nWICHTIG für deine Antwort:\n' +
  '1. Beantworte die Nutzerfrage gemäß deiner Prompt-Spezifikation oben\n' +
  '2. Am ENDE deiner Antwort hänge IMMER folgenden Block an:\n\n' +
  '<<<META>>>\n' +
  '{\n' +
  '  "next_steps": [{"id": "<prompt_id>", "label": "<kurzer Aktionstext>"}],\n' +
  '  "escalation_suggested": <true|false>,\n' +
  '  "escalation_target": "<prompt_id oder null>",\n' +
  '  "escalation_reason": "<warum vertiefen, oder null>"\n' +
  '}\n' +
  '<<<END_META>>>\n\n' +
  '- next_steps: 1-3 sinnvolle Folgeprompts aus der verfügbaren Liste\n' +
  '- escalation_suggested: true wenn aktueller Prompt quick ist UND Vertiefung sinnvoll wäre\n' +
  '- escalation_target: ID des Full-Prompts der eskaliert werden sollte (oder null)\n' +
  '- escalation_reason: kurzer Satz warum Vertiefung sinnvoll wäre (oder null)';

const systemPrompt = (typeof mdContent === 'string' ? mdContent : JSON.stringify(mdContent))
  + pastContext
  + relatedSection
  + escalationSection
  + outputInstruction;

// Query-Embedding für späteren Store-Schritt durchreichen
const queryEmbedding = $('Voyage Embedding').first().json.data[0].embedding;

return [{
  json: {
    systemPrompt,
    userQuestion: routing.user_question,
    sessionId: routing.sessionId,
    userId: routing.userId,
    promptId: routing.prompt_id,
    promptName: routing.promptName,
    targetAgent: routing.target_agent,
    depth: routing.depth,
    relatedDetails: routing.relatedDetails,
    escalationCandidate,
    queryEmbedding
  }
}];

// Antwort + META-Block aufbereiten (Buttons + Eskalation)
const rawAnswer = $input.first().json.output;
const routing = $('Build System Prompt').first().json;

let cleanAnswer = rawAnswer;
let meta = {
  next_steps: [],
  escalation_suggested: false,
  escalation_target: null,
  escalation_reason: null
};

// META-Block extrahieren (neues Format)
const metaMatch = rawAnswer.match(/<<<META>>>([\s\S]*?)<<<END_META>>>/);
if (metaMatch) {
  try {
    meta = JSON.parse(metaMatch[1].trim());
  } catch (e) {
    // Fallback wenn JSON kaputt — meta bleibt wie initialisiert
  }
  cleanAnswer = rawAnswer.replace(/<<<META>>>[\s\S]*?<<<END_META>>>/, '').trim();
}

// Fallback: alter NEXT_STEPS-Block (für Übergangsphase)
if (!metaMatch) {
  const oldMatch = rawAnswer.match(/<<<NEXT_STEPS>>>([\s\S]*?)<<<END_NEXT_STEPS>>>/);
  if (oldMatch) {
    try {
      const oldData = JSON.parse(oldMatch[1].trim());
      meta.next_steps = oldData.buttons || [];
    } catch (e) {}
    cleanAnswer = rawAnswer.replace(/<<<NEXT_STEPS>>>[\s\S]*?<<<END_NEXT_STEPS>>>/, '').trim();
  }
}

// Markdown-Block am Ende der Antwort: Eskalations-Hinweis + Folgeprompts
let appendix = '';

if (meta.escalation_suggested && meta.escalation_target) {
  appendix += '\n\n---\n\n### Vertiefung empfohlen\n';
  if (meta.escalation_reason) {
    appendix += `${meta.escalation_reason}\n\n`;
  }
  appendix += `Antworte mit **"Ja, vertiefen mit ${meta.escalation_target}"**, um die Tiefenanalyse zu starten.`;
}

if (meta.next_steps && meta.next_steps.length > 0) {
  appendix += '\n\n---\n\n**Mögliche nächste Schritte:**\n';
  appendix += meta.next_steps.map(b => `- 🔹 \`${b.id}\` — ${b.label}`).join('\n');
  appendix += '\n\n_Tipp: Stelle deine Folgefrage mit Bezug auf einen dieser Prompts._';
}

const finalOutput = cleanAnswer + appendix;

return [{
  json: {
    output: finalOutput,
    text: finalOutput,
    promptUsed: routing.promptName,
    promptId: routing.promptId,
    sessionId: routing.sessionId,
    suggestedNextPrompts: meta.next_steps,
    escalation: {
      suggested: meta.escalation_suggested,
      target: meta.escalation_target,
      reason: meta.escalation_reason
    },
    _meta: {
      depth: routing.depth,
      targetAgent: routing.targetAgent
    }
  }
}];

