// Hole die echte Antwort von Format Output + Buttons
const formatOutput = $('Format Output + Buttons').first().json;

return [{
  json: {
    output: formatOutput.output,
    text: formatOutput.text || formatOutput.output
  }
}];

// Die Daten sind in input.json.data
const content = $input.first().json.data;

if (!content || typeof content !== 'string') {
  return [{ body: content }];
}

// Suche nach <s>...</s> Block
let match = content.match(/```xml\s*<s>[\s\S]*?<\/s>\s*```/m);

if (match) {
  return [{
    body: match[0]
      .replace(/```xml\s*/g, '')
      .replace(/\s*```/g, '')
      .trim()
  }];
}

// Fallback: <s>...</s> ohne Backticks
match = content.match(/<s>[\s\S]*?<\/s>/m);
if (match) {
  return [{
    body: match[0]
  }];
}

// Wenn nichts gefunden: ganze Datei
return [{
  body: content
}];

// Klärungs-Antwort an den Chat zurückgeben (kein Executor, kein RAG, kein Store)
const data = $input.first().json;

const question = data.clarification_question || 'Können Sie Ihr Anliegen bitte konkretisieren?';
const reasoning = data.reasoning || '';

// Markdown-formatierte Rückfrage
const output = `❓ **Rückfrage zur besseren Beratung**\n\n${question}\n\n---\n*Ich frage nach, weil eine zielgerichtete Antwort eine konkretere Frage braucht. Antworten Sie einfach in der nächsten Nachricht.*`;

return [{
  json: {
    output: output,
    text: output,
    _meta: {
      isClarification: true,
      routerReasoning: reasoning,
      sessionId: data.sessionId,
      userId: data.userId
    }
  }
}];
